     "text": "Subject: Parking lot repaving\n\nDear colleagues,\n\nBeginning Monday, June 9, the parking lot behind Building B {{1}} for repaving. The work is expected to take five days. {{2}} Employees who normally park there are asked to use the lot on Harbor Street, which has plenty of space for everyone. A free shuttle will run between the two sites every ten minutes from 7:30 A.M. to 9:30 A.M. and again from 4:30 P.M. to 6:30 P.M.\n\n{{3}}, the main entrance on Oak Avenue will remain open, so deliveries will not be affected. We apologize for any inconvenience and thank you for your {{4}}.\n\nKaren Mills\nFacilities Manager",
