     "id": "P6-03",
     "doc": "article",
     "text": "BRIDGEPORT (June 12) – Harlan Textiles announced that it will build a second factory in Dunmore, about 40 kilometers north of its current headquarters. The new facility {{1}} 200 jobs when it opens in early 2028, company president Elaine Voss said. Voss explained that the Bridgeport factory has reached full capacity and can no longer keep up with orders from overseas buyers. “Demand has grown steadily for three years,” she said. {{2}}\n\nDunmore officials welcomed the news. Mayor Paul Reyes said the project, {{3}} will cost an estimated $30 million, would give young residents a reason to stay in the area. {{4}}, some neighbors have expressed concern about increased truck traffic on Route 9. The company has promised to hold a public meeting next month to address such concerns.",
