       "type": "letter",
       "title": "Willowbrook Botanical Garden",
       "text": "Willowbrook Botanical Garden\n2200 Ashby Road, Millhaven\n\nOctober 9\n\nMr. Oscar Venn\n117 Quarry Lane\nMillhaven\n\nDear Mr. Venn,\n\nYour Family Membership at Willowbrook Botanical Garden will expire on November 30. Over the past year, your household visited us eleven times, and we were delighted to see your children take part in our Saturday seed-planting workshops. On behalf of everyone here, thank you for your loyal support.\n\nI am writing to let you know about several changes taking effect on January 1. The annual fee for Family Membership will rise from $85 to $95, the first increase in four years; it will fund the restoration of the Victorian glasshouse, which has been closed since March. In return, all members will receive free admission to the Winter Lantern Festival, which previously required a separate ticket costing $12 per person. Members will also be able to reserve workshop places two weeks earlier than the general public.\n\nIf you renew before November 15, you can keep the current fee of $85 for the entire next year. Renewals may be completed online, by mail with the enclosed form, or in person at the visitor center, which is open daily except Mondays. Please note that members who let their memberships lapse for more than 30 days must pay a $10 reinstatement charge.\n\nWe hope to see you and your family among the gardens again soon.\n\nSincerely,\n\nHarriet Cole\nDirector of Membership"
