       "type": "web page",
       "title": "BlueTide Kayak Adventures",
       "text": "BlueTide Kayak Adventures - Tours & Policies\nHome | Tours | Booking | Contact\n\nOur guided tours depart from the Pelican Cove dock, 15 minutes north of the town of Seaford. [1] Every group is led by two certified guides and is limited to twelve paddlers so that everyone receives personal attention.\n\nTOURS\nSunrise Paddle (2 hours, $55): Glide along the quiet shoreline as the sun rises and look for herons and seals. Departs at 6:00 A.M.; suitable for beginners.\nSea Cave Explorer (4 hours, $95): Navigate through rock arches and caves. Prior kayaking experience is required, and first-time paddlers cannot be accepted. [2] Tours operate only at low tide, so departure times change daily; please check the online calendar.\nIsland Picnic (6 hours, $130): Paddle to Gull Island for a guided walk and a lunch prepared by a local caterer. Vegetarian meals are available on request.\n\nBOOKING AND CANCELLATIONS\nReservations are confirmed once a 25 percent deposit is paid. Cancellations made at least 72 hours before departure receive a full refund of the deposit. [3] Cancellations made within 72 hours forfeit the deposit unless the tour is canceled by BlueTide because of weather. Guests who are unable to join may transfer their booking to another person at no charge.\n\nWHAT TO BRING\nWear clothing that can get wet, and bring sunscreen and a water bottle. Life jackets, paddles, and waterproof bags are provided free of charge. [4] Cameras are welcome, but we recommend using a waterproof case, as BlueTide cannot be responsible for damaged equipment.\n\nChildren aged 10 and older may join the Sunrise Paddle with an adult."
