       "type": "memo",
       "title": "Castellan Logistics",
       "text": "MEMORANDUM\n\nTo: All Employees, Castellan Logistics\nFrom: Beatrice Okafor, Director of Human Resources\nDate: January 8\nSubject: Revised Remote Work Policy\n\nAfter a three-month trial in the Operations and Accounting departments, the executive team has approved a revised remote work policy that will apply to all offices beginning February 3. The trial showed that employees who worked from home up to two days a week reported higher satisfaction, while customer-response times remained unchanged. However, it also revealed that teams whose members worked on completely different days struggled to hold meetings, so the new policy includes a core-day requirement.\n\nKey points:\n\n1. Eligibility. Employees who have completed six months of service may work remotely up to two days per week with supervisor approval. Employees on the Warehouse Operations team, whose duties must be performed on site, are not eligible but may apply for a flexible start-time schedule instead.\n\n2. Core days. All employees, regardless of their remote arrangements, are expected to be in the office every Tuesday and Thursday.\n\n3. Equipment. The company will provide a laptop and headset. A one-time allowance of $150 is available for a monitor or other ergonomic equipment; receipts must be submitted to Accounting within 30 days of purchase. Home internet costs will not be reimbursed.\n\n4. Application. Requests should be submitted through the HR portal by January 24. Applications received after that date will be processed in the following quarter.\n\nSupervisors will hold individual meetings with team members during the week of January 20 to discuss schedules. Employees who participated in the trial need not reapply, but their current arrangements will be reviewed to ensure they meet the new core-day rule. Questions may be directed to Ms. Okafor at extension 310."
