       "type": "advertisement",
       "text": "Brightway Freight\nNow Hiring: Logistics Coordinator - Tacoma Office\n\nBrightway Freight, a regional shipping company, is looking for a Logistics Coordinator to manage deliveries between our warehouses and customers across the Pacific Northwest.\n\nResponsibilities:\n- Plan delivery routes and track shipments\n- Communicate with drivers and warehouse staff\n- Prepare weekly reports for the operations manager\n\nRequirements:\n- At least two years of experience in logistics or a related field\n- Working knowledge of inventory management software\n- Fluent Spanish is preferred but not required\n\nSalary: $48,000 to $55,000 per year, depending on experience. Benefits include health insurance, 15 days of paid vacation, and a yearly training allowance. Our Tacoma office is located five minutes from the central train station, and free parking is available for all employees.\n\nTo apply, send your resume and a cover letter to hiring@brightwayfreight.example by November 20. Interviews will be held on December 1 and 2. The successful candidate will start on January 11.",
