       "type": "web page",
       "text": "Ridgeline Office Supply\nDelivery and Returns Information\n\nStandard Delivery\nIn-stock items are shipped within one business day and arrive in 5 to 7 business days. Delivery is FREE on orders of $400 or more after discounts are applied. For smaller orders, a flat delivery charge of $18 applies.\n\nMade-to-Order Items\nItems marked \"MTO\" (such as bookshelves and custom desks) are built after your order is placed. They are delivered within three weeks of the order date. When an order includes both in-stock and MTO items, we ship the in-stock items immediately and send the MTO items separately at no additional charge.\n\nPromotions\nA promotion code can be entered at checkout. Only one code may be used per order.\n\nReturns\nUnused items may be returned within 30 days of delivery. Customers pay return shipping costs unless the item arrived damaged or defective. MTO items cannot be returned unless damaged or defective.\n\nItems that are out of stock will be marked clearly on the product page. Questions? Contact customer service at help@ridgelineoffice.example.",
       "title": "Ridgeline Office Supply"
