       "e": "Most of these areas are closed to the public が根拠。衣装工房や楽屋など、ふだん一般公開していない場所を回ることを usually off-limits と言い換えた。案内役が出演者だとも、最後に上演があるとも言っていない。",
       "tag": "詳細",
       "num": 86
