     "id": "M02-P6-03",
     "doc": "article",
     "text": "ROWANFORD (September 8) — The Rowanford Growers' Cooperative will open a year-round indoor market next spring in the former Jessop's department store on Pine Street. For the past twelve years, the cooperative's farmers {{1}} their produce at an outdoor market that runs only from May to October.\n\n\"Our members have wanted a permanent home for a long time,\" said cooperative director Ellen Hargrove. \"{{2}}\"\n\nThe building's ground floor will be divided into forty stalls, and the upper floor will host cooking classes and a small café. Renovation work is {{3}} to begin in November. The cooperative is still looking for vendors for about ten of the stalls. Local food producers {{4}} are interested in renting space should contact the cooperative by October 15.",
     "sum": "地元の生産者協同組合が、元百貨店の建物に通年営業の屋内市場を来春開くという記事。11月に改装が始まり、残りの売り場の出店者を募集している。",
