       "a": 1,
       "tag": "文法",
       "e": "For the past twelve years は12年前から今まで続くことを表すので、現在完了進行形が入る。屋外市場は今も5〜10月に開かれている。過去完了進行形は過去の基準となる時がなく、未来進行形と過去進行形は期間の表現と合わない。",
