       "text": "QUILLFIELD STUDIOS\nHome | Rooms | Rates | FAQ\n\nRecord with Confidence\nWhether you are launching a company podcast or producing training videos, Quillfield Studios gives you a professional recording space without the expense of building your own. [1] Our two soundproof rooms are on the fourth floor of the Larchmont Building, a five-minute walk from Ferris Square Station.\n\nROOMS\nStudio A seats up to four people and is ideal for interviews and panel discussions. Studio B is a single-person booth designed for voice-overs and audiobook narration. Both rooms are fully air-conditioned and have high-speed internet access. [2]\n\nRATES\nStudio A: $70 per hour\nStudio B: $45 per hour\nAll bookings must be at least two hours long. Every booking includes the services of a sound engineer, who will set up the microphones and monitor recording levels throughout your session. [3]\n\nEDITING\nNeed help after your session? Our editors can remove background noise, add music, and deliver finished files within three business days for an additional $40 per hour of recorded audio.\n\nCANCELLATIONS\nSessions canceled more than 48 hours in advance may be rescheduled at no charge. [4] Later cancellations will be billed at half the booking price."
