       "type": "letter",
       "title": "Palisade Museum of Art",
       "text": "Palisade Museum of Art\n45 Corliss Avenue, Westmoor\n\nAugust 18\n\nMs. Adele Moreau\n29 Vantage Road\nWestmoor\n\nDear Ms. Moreau,\n\nOn behalf of the Palisade Museum of Art, thank you for agreeing to lend Orchard in Winter by Elsa Varga to our autumn exhibition, Light on the Land: Regional Painters, 1890-1940. The exhibition will run from October 10 to January 25, and your painting will hang in the main gallery beside two other works by the same artist.\n\nAs you discussed with our registrar, Julian Nwosu, the museum will cover every cost related to the loan. A team of specialist art handlers will pack the painting at your home on September 22, and it will be transported in a climate-controlled vehicle. From the moment it leaves your home until it is returned, the painting will be insured for its full value under the museum's policy, so you will not need to arrange any coverage of your own.\n\nUnless you instruct us otherwise, the label beside the painting and the entry in the exhibition catalog will read \"Lent by a private collector.\" If you would prefer to have your name appear, please inform Mr. Nwosu by September 1, when the catalog goes to the printer.\n\nI am also pleased to invite you and a guest to a preview reception for lenders and museum members on the evening of October 9. A formal invitation will follow next month.\n\nTwo copies of the loan agreement are enclosed. Please sign both, keep one for your records, and return the other in the envelope provided.\n\nSincerely,\n\nGabriel Ocampo\nChief Curator"
