       "title": "Travel Expense Changes",
       "text": "MEMO\n\nTo: Sales and service staff\nFrom: Lydia Varga, Finance Director\nDate: May 2\nSubject: Changes to travel expense claims\n\nStarting June 1, Kelbridge Instruments will no longer reimburse meals on the basis of individual receipts. Instead, employees traveling on company business will receive a fixed daily meal allowance. The amount depends on the destination:\n\nCategory A (Boston, Chicago, New York, San Francisco)   $70 per day\nCategory B (all other U.S. cities)                       $55 per day\nInternational destinations                               $85 per day\n\nThe full rate applies to each complete day away from home. For the day of departure and the day of return, travelers will receive 75 percent of the daily rate.\n\nThere is no change to the rules for hotels: rooms booked through the company travel portal will continue to be paid for in full. Taxi fares between airports and hotels are also covered. However, rental cars must now be approved in advance by your department manager, and requests made after a rental has begun will not be accepted. Receipts are still required for all lodging and transportation costs.\n\nClaims should be filed in the online expense system within 30 days of your return. Claims filed after this period will be processed only with written approval from a director.\n\nQuestions about these changes may be directed to Ian Walsh in the finance department (ext. 418)."
