       "type": "e-mail",
       "text": "To: Maya Velasquez\nFrom: Simon Rourke\nDate: May 14\nSubject: Your night market application\n\nDear Ms. Velasquez,\n\nThank you for applying to sell at the Weller Square Night Market. I am pleased to tell you that Copper Spoon Kitchen has been offered a space for all of the nights you requested. However, because we received a record number of applications this year, every space in Zone A has gone to a vendor who will be at the market each week of the season. We can instead offer you space B-7 in Zone B, which is right next to the main entrance. If you need power, you may bring a quiet portable generator, as long as our staff have checked it before you use it.\n\nPlease also note that we have not yet received one of the documents we require for your type of business. It must reach us by June 20, or we will have to give your space to the next vendor on our waiting list.\n\nIf a space in Zone A becomes available, I will contact you immediately. Please reply by May 23 to let us know whether you accept space B-7.\n\nBest regards,\nSimon Rourke\nEvents Office, City of Selbury"
